def clean(df):
    df = df.copy()
    df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce')
    df = df[(df['flipper_length_mm'] >= 170) & (df['flipper_length_mm'] <= 235)]
    return df

def answer(df):
    df = clean(df)
    g = df.groupby('species')['flipper_length_mm'].mean()
    return {k: float(v) for k, v in g.items() if pd.notna(k)}
